function Write-P5Json([string]$Name,$Value){$taskText=($Value|ConvertTo-Json -Depth 24)-replace "`r`n","`n";[IO.File]::WriteAllText((Join-Path $taskOwn $Name),$taskText+"`n",[Text.UTF8Encoding]::new($false))}
