$taskTargets=Get-Content (Join-Path $taskRuntime 'refs/targets.json') -Raw|ConvertFrom-Json
$taskSpecs=@(
 @{name='floor-v1';family='floor';anchor=@(0,0);width=1254;depth=1254;record='001-floor-v1.json';note='Opaque new generated square plate; exact registration remains unverified'},
 @{name='ball-v1';family='ball';anchor=@(625,1147);width=1052;depth=1052;record='ball-v1.json';note='Sphere visible bbox center[625,624], diameter1052; contact at lower half-open bbox edge. Manual optical estimate about3px; no baked shadow'},
