 if((Get-FileHash -LiteralPath $taskFinal -Algorithm SHA256).Hash.ToLowerInvariant() -ne $taskMeasure.sha256 -or (Get-Item -LiteralPath $taskFinal).Length -ne $taskMeasure.bytes){throw 'Selected bytes mismatch'}
 $taskTexture=[ordered]@{id=$taskSpec.name;family=$taskSpec.family;file=$taskFinal.Replace('\','/');sha256=$taskMeasure.sha256;bytes=$taskMeasure.bytes;sizePx=@($taskMeasure.image.width,$taskMeasure.image.height);alpha=@{policy=$(if($taskSpec.family -eq 'floor'){'opaque'}else{'straight-rgba'});bounds=$taskMeasure.image.bounds;visibleBounds=$taskMeasure.image.visibleBounds;maxAlpha=$taskMeasure.image.maxAlpha;opaquePixels=$taskMeasure.image.opaquePixels;note='Exact alpha>0 and alpha>=16 half-open bounds. Native alpha retained; no trim/threshold/color correction.'};groundAnchorPx=$taskSpec.anchor;footprintPx=@{center=$taskSpec.anchor;width=$taskSpec.width;depth=$taskSpec.depth;measurement=$taskSpec.note};provenance=@{method='generated';promptPath=$taskRecord.prompt;promptSha256=(Get-FileHash -LiteralPath (Join-Path $taskOwn $taskRecord.prompt) -Algorithm SHA256).Hash.ToLowerInvariant();toolOutputId=$taskRecord.toolOutputId;rawSha256=$taskMeasure.sha256;rawFile=$taskRaw.Replace('\','/');nativeOutputPath=$taskRecord.source;corrections=@();selection='Unchanged native pixels; partial integration candidate, no runtime/artistic PASS';references=$taskRecord.references}}
 if($taskSpec.family -eq 'ball'){$taskTexture.sphereVisualCenterPx=@(625,624);$taskTexture.contactLiftTexturePx=523}
 $taskTexture
})
$taskInstances=[System.Collections.Generic.List[object]]::new()
